q1:"अगर मुझे अपना सही जन्म समय नहीं पता तो?", a1:"फिर भी उपयोगी विश्लेषण संभव है। हम जन्म-समय संशोधन करते हैं, या प्रश्न कुंडली पर जाते हैं, जो प्रश्न पूछने के क्षण से बनती है और जिसमें जन्म समय की ज़रूरत नहीं होती।",
q2:"क्या मेरी निजी जानकारी गोपनीय रहती है?", a2:"हाँ, पूरी तरह। आपका जन्म विवरण और सारी बातचीत केवल आपके और आचार्य गौतम के बीच रहती है। कुछ भी साझा, बेचा या प्रकाशित नहीं किया जाता।",
q3:"क्या आप मुंबई के बाहर भी परामर्श देते हैं?", a3:"ऑनलाइन परामर्श वीडियो या फोन द्वारा दुनिया में कहीं भी उपलब्ध है। वास्तु साइट विज़िट फिलहाल मुंबई और एमएमआर क्षेत्र में; अन्य शहरों के लिए यात्रा अलग से तय की जा सकती है।",
q4:"क्या मुझ पर रत्न या पूजा खरीदने का दबाव डाला जाएगा?", a4:"नहीं। उपाय केवल तभी सुझाए जाते हैं जब वास्तव में ज़रूरी हों, और पहले हमेशा सरल विकल्प दिए जाते हैं। कुछ भी खरीदना अनिवार्य नहीं है।",
q5:"रिपोर्ट कितनी जल्दी मिलेगी?", a5:"परामर्श के बाद लिखित रिपोर्ट 24 से 48 घंटों में मिल जाती है। तत्काल प्रश्न कुंडली का उत्तर आमतौर पर उसी दिन दिया जाता है।",
