calc_sub:"तुमचा मूलांक, भाग्यांक आणि मोबाइल नंबरचे कंपन काही सेकंदात जाणून घ्या. मोफत, तात्काळ आणि काहीही साठवले जात नाही.",
calc_note:"आमची मोबाइल अंकशास्त्र सल्लामसलत याच गणनेपासून सुरू होते — सशुल्क विश्लेषणात ते तुमच्या पूर्ण कुंडलीशी जोडून पाहिले जाते.",
