calc_good:"तुमचा मोबाइल नंबर तुमच्या मूलांकाशी सुसंगत आहे. स्थैर्य आणि पैशाच्या प्रवाहासाठी चांगला.",
calc_ok:"तुमचा मोबाइल नंबर तटस्थ आहे — फायदाही नाही, तोटाही नाही. छोट्या बदलाने सुधारणा होऊ शकते.",
