calc_nomob:"नंबर तुमच्या मूलांकाशी जुळतो का हे पाहण्यासाठी तुमचा मोबाइल नंबरही भरा.",
prod_eyebrow:"स्टोअर",
prod_title:"यंत्रे, ब्रेसलेट आणि वास्तु वस्तू",
prod_sub:"प्रत्येक वस्तू पाठवण्यापूर्वी आचार्य गौतम अभिमंत्रित करतात, आणि तुमच्या कुंडलीत खरोखर गरज असेल तेव्हाच सुचवली जाते.",
prod_note:"कोणती घ्यावी कळत नाही? आधी विचारा — गरज नसेल तर आम्ही स्पष्ट सांगू.",
