tools_title:"पंचांग, चंद्र आणि अंक",
tools_sub:"तीन गोष्टी ज्या तुम्ही आत्ता, मोफत पाहू शकता. सर्व गणना तुमच्याच ब्राउझरमध्ये होते — काहीही साठवले किंवा कुठेही पाठवले जात नाही.",
