pan_tithi:"तिथी",
pan_nak:"नक्षत्र",
pan_yoga:"योग",
pan_karana:"करण",
pan_vara:"वार",
pan_moon:"चंद्र राशी",
pan_sun:"सूर्य राशी",
pan_sunrise:"सूर्योदय",
pan_sunset:"सूर्यास्त",
pan_rahu:"राहू काळ",
pan_abhijit:"अभिजित मुहूर्त",
pan_ayan:"अयनांश",
pan_note:"निवडलेल्या शहराच्या सूर्योदयानुसार गणना. विवाह, नोंदणी किंवा वास्तुशांतीपूर्वी अचूक मुहूर्तासाठी आचार्य गौतम यांना विचारा — छापील पंचांग तुमची कुंडली पाहू शकत नाही.",
moon_intro:"आज चंद्र {sign} राशीत, {nak} नक्षत्रात आहे. प्रत्येक जन्म राशीपासून त्याचे स्थान खाली दिले आहे.",
moon_good:"अनुकूल",
moon_mixed:"सामान्य",
moon_bad:"काळजी घ्या",
moon_note:"हे चंद्रबल आहे — तुमच्या जन्म राशीपासून आजचा चंद्र कुठे आहे. हा अनेक घटकांपैकी एक आहे, तुमच्या दिवसाचा निर्णय नाही.",
s7_n:"कुंडली जुळणी",
s7_d:"दोन्ही कुंडल्यांची संपूर्ण 36 गुण अष्टकूट जुळणी, तसेच मंगळ दोष, आयुर्विचार आणि कुटुंब खरोखर विचारते ते व्यावहारिक प्रश्न.",
s8_n:"मुहूर्त निवड",
s8_d:"विवाह, नोंदणी, वास्तुशांती, शस्त्रक्रिया किंवा नव्या कामासाठी योग्य तारीख आणि वेळ — तुमची कुंडली पाहून निवडलेली, छापील पंचांगातून नाही.",
lbl_both:"दोन्ही कुंडल्या",
lbl_perevent:"प्रति कार्यक्रम",
modes_eyebrow:"सल्ला",
modes_title:"गौतम यांच्याशी बोलण्याचे चार मार्ग",
modes_sub:"तुम्ही कोणताही निवडा, ज्योतिषी दरवेळी तेच असतील. चॅट प्रति मिनिट आहे; व्हॉइस, व्हिडिओ आणि प्रत्यक्ष भेट ठराविक शुल्कात — कोणतेही मीटर चालत नाही.",
m1_n:"लाइव्ह चॅट",
m1_d:"तुमचा प्रश्न लिहा, विचारपूर्वक दिलेले उत्तर मिळवा. सुरुवात करण्याचा सर्वात सोपा मार्ग.",
m2_n:"व्हॉइस सल्लामसलत",
m2_d:"एक सविस्तर फोन संवाद. तुम्हाला तुमच्या शब्दांत परिस्थिती सांगायची असेल तेव्हा सर्वोत्तम.",
m3_n:"व्हिडिओ सल्लामसलत",
