faq_title:"વારંવાર પૂછાતા પ્રશ્નો",
q1:"મને મારો ચોક્કસ જન્મ સમય ખબર ન હોય તો?", a1:"તો પણ ઉપયોગી વાચન શક્ય છે. અમે જન્મ-સમય સુધારણા કરીએ છીએ, અથવા પ્રશ્ન કુંડળી પર જઈએ છીએ — જે પ્રશ્ન પૂછ્યાની ક્ષણથી બને છે અને જેમાં જન્મ સમયની જરૂર જ નથી.",
q2:"શું મારી અંગત માહિતી ગોપનીય રહે છે?", a2:"હા, સંપૂર્ણપણે. તમારી જન્મ વિગતો અને બધી ચર્ચા ફક્ત તમારા અને આચાર્ય ગૌતમ વચ્ચે જ રહે છે. કંઈ પણ વહેંચાતું, વેચાતું કે પ્રકાશિત થતું નથી.",
q3:"શું તમે મુંબઈ બહાર પણ પરામર્શ આપો છો?", a3:"ઓનલાઇન પરામર્શ વિડિયો કે ફોન દ્વારા દુનિયામાં ક્યાંય પણ ઉપલબ્ધ છે. વાસ્તુ સાઇટ વિઝિટ હાલમાં મુંબઈ અને એમએમઆર વિસ્તારમાં; અન્ય શહેરો માટે પ્રવાસ અલગથી નક્કી કરી શકાય છે.",
q4:"શું મને રત્નો કે પૂજા ખરીદવાનું દબાણ કરવામાં આવશે?", a4:"ના. ખરેખર જરૂર હોય ત્યાં જ ઉપાયો સૂચવાય છે અને હંમેશા પહેલાં સરળ વિકલ્પો અપાય છે. કંઈ પણ ખરીદવું ફરજિયાત નથી.",
q5:"રિપોર્ટ કેટલો જલદી મળશે?", a5:"પરામર્શ પછી લેખિત રિપોર્ટ 24 થી 48 કલાકમાં મળે છે. તાત્કાલિક પ્રશ્ન કુંડળીનો જવાબ સામાન્ય રીતે એ જ દિવસે અપાય છે.",
form_title:"તમારો પરામર્શ બુક કરો", form_sub:"આ ભરો અને અમે વોટ્સએપ પર વાત આગળ વધારીશું. આ તબક્કે કોઈ ચુકવણી નથી.",
