q1:"আমার সঠিক জন্মসময় জানা না থাকলে?", a1:"তবুও কার্যকর বিশ্লেষণ সম্ভব। আমরা জন্মসময় সংশোধন করি, অথবা প্রশ্ন কুণ্ডলীতে যাই — যা প্রশ্ন করার মুহূর্ত থেকে তৈরি হয় এবং যাতে জন্মসময়ের প্রয়োজনই নেই।",
