q4:"আমাকে কি রত্ন বা পূজা কিনতে চাপ দেওয়া হবে?", a4:"না। সত্যিই প্রয়োজন হলে তবেই প্রতিকার বলা হয়, এবং সবসময় আগে সহজ বিকল্প দেওয়া হয়। কিছু কেনা বাধ্যতামূলক নয়।",
