hero_badge:"25+ ஆண்டுகள் வேத அனுபவம் · மும்பை",
hero_h1:"வாழ்க்கையின் பெரிய முடிவுகளுக்குத் தெளிவான வழிகாட்டுதல்",
hero_sub:"ஆசார்ய கௌதம் நாயக்கிடமிருந்து வேத ஜோதிடம், வாஸ்து சாஸ்திரம் மற்றும் எண் கணித வழிகாட்டுதல் — நடைமுறைக்கு ஏற்ற, ரகசியமான, 25 ஆண்டுகள் நிஜ அனுபவத்தின் அடிப்படையில்.",
hero_cta1:"இலவச 5-நிமிட ஆலோசனை பெறுங்கள்", hero_cta2:"அனைத்து சேவைகளையும் பார்க்க",
hero_note:"தொடங்க கட்டணம் இல்லை · பொதுவாக 2 மணி நேரத்தில் பதில் · உங்கள் தகவல் ரகசியமாக இருக்கும்",
