calc_cta:"இதை ஆசார்ய கௌதமுக்கு அனுப்பு",
calc_good:"உங்கள் கைபேசி எண் உங்கள் மூலாங்கத்துடன் இணக்கமாக உள்ளது. நிலைத்தன்மைக்கும் பண வரவுக்கும் நல்லது.",
calc_ok:"உங்கள் கைபேசி எண் நடுநிலையானது — நன்மையும் இல்லை, தீமையும் இல்லை. சிறு மாற்றம் மேம்படுத்தலாம்.",
calc_check:"உங்கள் கைபேசி எண் உங்கள் மூலாங்கத்துடன் இணக்கமாக இல்லை. மாற்றுவதற்கு முன் ஒருமுறை பரிசீலிக்கவும்.",
calc_nomob:"எண் உங்கள் மூலாங்கத்திற்குப் பொருந்துகிறதா என அறிய கைபேசி எண்ணையும் பதிவிடுங்கள்.",
prod_eyebrow:"கடை",
prod_title:"யந்திரங்கள், கைவளையல்கள் மற்றும் வாஸ்து பொருட்கள்",
prod_sub:"ஒவ்வொரு பொருளும் அனுப்பும் முன் ஆசார்ய கௌதமால் சக்தியூட்டப்படுகிறது, உங்கள் ஜாதகம் உண்மையிலேயே கோரும்போது மட்டுமே பரிந்துரைக்கப்படுகிறது.",
prod_note:"எது பொருத்தம் எனத் தெரியவில்லையா? முதலில் கேளுங்கள் — தேவையில்லை என்றால் நேரடியாகச் சொல்வோம்.",
