prod_vastu:"வாஸ்து",
tools_title:"பஞ்சாங்கம், சந்திரன் & எண்கள்",
tools_sub:"இப்போதே இலவசமாகப் பார்க்கக்கூடிய மூன்று விஷயங்கள். அனைத்தும் உங்கள் உலாவியிலேயே கணக்கிடப்படுகிறது — எதுவும் சேமிக்கப்படுவதோ அனுப்பப்படுவதோ இல்லை.",
