pan_abhijit:"அபிஜித் முகூர்த்தம்",
pan_ayan:"அயனாம்சம்",
pan_note:"தேர்ந்தெடுத்த நகரத்தின் சூரிய உதயத்தின்படி கணக்கிடப்பட்டது. திருமணம், பதிவு அல்லது கிரகப்பிரவேசத்திற்கு முன் சரியான முகூர்த்தத்திற்கு ஆசார்ய கௌதமிடம் கேளுங்கள் — அச்சிடப்பட்ட பஞ்சாங்கம் உங்கள் ஜாதகத்தைப் பார்க்க முடியாது.",
moon_intro:"இன்று சந்திரன் {sign} ராசியில், {nak} நட்சத்திரத்தில் உள்ளது. ஒவ்வொரு ஜென்ம ராசியிலிருந்தும் அதன் நிலை கீழே.",
moon_good:"சாதகம்",
moon_mixed:"நடுநிலை",
moon_bad:"கவனம்",
moon_note:"இது சந்திர பலம் — உங்கள் ஜென்ம ராசியிலிருந்து இன்றைய சந்திரன் எங்கே உள்ளது. இது பல காரணிகளில் ஒன்று, உங்கள் நாளின் தீர்ப்பு அல்ல.",
s7_n:"ஜாதகப் பொருத்தம்",
s7_d:"இரு ஜாதகங்களுக்கும் முழு 36 குண அஷ்டகூட பொருத்தம், மங்கள் தோஷம், ஆயுள் பரிசீலனை மற்றும் குடும்பங்கள் உண்மையில் கேட்கும் நடைமுறைக் கேள்விகள்.",
s8_n:"முகூர்த்தம் நிர்ணயம்",
s8_d:"திருமணம், பதிவு, கிரகப்பிரவேசம், அறுவை சிகிச்சை அல்லது புதிய தொழிலுக்கான சரியான நாளும் நேரமும் — உங்கள் ஜாதகத்தைப் பார்த்துத் தேர்ந்தெடுத்தது, அச்சிட்ட பஞ்சாங்கத்திலிருந்து அல்ல.",
lbl_both:"இரு ஜாதகங்கள்",
lbl_perevent:"நிகழ்வுக்கு",
modes_eyebrow:"ஆலோசனை",
modes_title:"கௌதமிடம் பேச நான்கு வழிகள்",
modes_sub:"நீங்கள் எதைத் தேர்ந்தெடுத்தாலும் ஜோதிடர் ஒருவரே. அரட்டை நிமிடக் கணக்கில்; குரல், வீடியோ, நேரில் நிலையான கட்டணத்தில் — மீட்டர் ஓடாது.",
m1_n:"நேரலை அரட்டை",
m1_d:"கேள்வியைத் தட்டச்சு செய்யுங்கள், சிந்தித்த பதில் பெறுங்கள். தொடங்க எளிதான வழி.",
m2_n:"குரல் ஆலோசனை",
m2_d:"ஒரு முழுமையான தொலைபேசி உரையாடல். உங்கள் சொற்களில் நிலைமையை விளக்க விரும்பினால் சிறந்தது.",
m3_n:"வீடியோ ஆலோசனை",
m3_d:"ஆன்லைனில் நேருக்கு நேர். படிக்கும்போதே கௌதம் ஜாதகத்தைத் திரையில் காட்ட முடியும்.",
m4_n:"நேரில் சந்திப்பு",
m4_d:"மும்பை அலுவலகத்தில். குடும்ப விவகாரங்கள், நீண்டகாலத் திட்டமிடலுக்கு ஏற்றது.",
