f_note:"ఇది మీ వివరాలతో వాట్సాప్ తెరుస్తుంది. ఈ పేజీలో ఏదీ నిల్వ చేయబడదు.",
foot_tag:"వైదిక జ్యోతిష్యం, వాస్తు శాస్త్రం మరియు సంఖ్యా శాస్త్ర మార్గదర్శనం — 25 సంవత్సరాల అభ్యాసం ఆధారంగా.",
foot_links:"త్వరిత లింక్‌లు", foot_contact:"సంప్రదించండి", foot_addr:"ముంబై, మహారాష్ట్ర, భారతదేశం",
