s7_n:"కుండలి మిలన్",
s7_d:"రెండు జాతకాలకూ పూర్తి 36 గుణ అష్టకూట మేళనం, మంగళ దోషం, ఆయుర్దాయ పరిశీలన మరియు కుటుంబాలు నిజంగా అడిగే ఆచరణాత్మక ప్రశ్నలు.",
s8_n:"ముహూర్త నిర్ణయం",
s8_d:"వివాహం, రిజిస్ట్రీ, గృహప్రవేశం, శస్త్రచికిత్స లేదా కొత్త వ్యాపారానికి సరైన తేదీ, సమయం — మీ జాతకం చూసి ఎంచుకున్నది, ముద్రిత పంచాంగం నుండి కాదు.",
