lbl_perevent:"ప్రతి కార్యక్రమానికి",
modes_eyebrow:"సంప్రదింపు",
modes_title:"గౌతమ్‌తో మాట్లాడటానికి నాలుగు మార్గాలు",
modes_sub:"మీరు ఏది ఎంచుకున్నా జ్యోతిష్కుడు ఒక్కరే. చాట్ నిమిషాల లెక్కన; వాయిస్, వీడియో, ప్రత్యక్ష సమావేశం స్థిర రుసుముతో — మీటర్ నడవదు.",
m1_n:"లైవ్ చాట్",
m1_d:"మీ ప్రశ్న టైప్ చేయండి, ఆలోచించి ఇచ్చిన సమాధానం పొందండి. ప్రారంభించడానికి సులభమైన మార్గం.",
m2_n:"వాయిస్ సంప్రదింపు",
m2_d:"ఒక పూర్తి ఫోన్ సంభాషణ. మీ మాటల్లో పరిస్థితిని వివరించాలనుకుంటే ఉత్తమం.",
