calc_bhagyank:"ಭಾಗ್ಯಾಂಕ",
calc_mobnum:"ಮೊಬೈಲ್ ಅಂಕಿ",
calc_cta:"ಇದನ್ನು ಆಚಾರ್ಯ ಗೌತಮ್‌ಗೆ ಕಳುಹಿಸಿ",
calc_good:"ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ನಿಮ್ಮ ಮೂಲಾಂಕದೊಂದಿಗೆ ಹೊಂದಿಕೊಂಡಿದೆ. ಸ್ಥಿರತೆ ಮತ್ತು ಹಣದ ಹರಿವಿಗೆ ಒಳ್ಳೆಯದು.",
calc_ok:"ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ತಟಸ್ಥವಾಗಿದೆ — ಲಾಭವೂ ಇಲ್ಲ, ಹಾನಿಯೂ ಇಲ್ಲ. ಸಣ್ಣ ಬದಲಾವಣೆಯಿಂದ ಸುಧಾರಿಸಬಹುದು.",
calc_check:"ನಿಮ್ಮ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ನಿಮ್ಮ ಮೂಲಾಂಕದೊಂದಿಗೆ ಹೊಂದಿಕೊಂಡಿಲ್ಲ. ಬದಲಾಯಿಸುವ ಮೊದಲು ಒಮ್ಮೆ ಪರಿಶೀಲಿಸಿ.",
