prod_note:"ಯಾವುದು ಸೂಕ್ತ ಎಂದು ತಿಳಿಯುತ್ತಿಲ್ಲವೇ? ಮೊದಲು ಕೇಳಿ — ಅಗತ್ಯವಿಲ್ಲದಿದ್ದರೆ ನೇರವಾಗಿ ಹೇಳುತ್ತೇವೆ.",
