pan_abhijit:"ಅಭಿಜಿತ್ ಮುಹೂರ್ತ",
pan_ayan:"ಅಯನಾಂಶ",
pan_note:"ಆಯ್ಕೆ ಮಾಡಿದ ನಗರದ ಸೂರ್ಯೋದಯದ ಪ್ರಕಾರ ಲೆಕ್ಕ. ಮದುವೆ, ನೋಂದಣಿ ಅಥವಾ ಗೃಹಪ್ರವೇಶಕ್ಕೆ ಮೊದಲು ನಿಖರ ಮುಹೂರ್ತಕ್ಕಾಗಿ ಆಚಾರ್ಯ ಗೌತಮ್ ಅವರನ್ನು ಕೇಳಿ — ಮುದ್ರಿತ ಪಂಚಾಂಗ ನಿಮ್ಮ ಜಾತಕವನ್ನು ನೋಡಲಾರದು.",
moon_intro:"ಇಂದು ಚಂದ್ರ {sign} ರಾಶಿಯಲ್ಲಿ, {nak} ನಕ್ಷತ್ರದಲ್ಲಿದ್ದಾನೆ. ಪ್ರತಿ ಜನ್ಮ ರಾಶಿಯಿಂದ ಅವನ ಸ್ಥಾನ ಕೆಳಗಿದೆ.",
