moon_mixed:"ಸಾಮಾನ್ಯ",
moon_bad:"ಎಚ್ಚರಿಕೆ",
moon_note:"ಇದು ಚಂದ್ರ ಬಲ — ನಿಮ್ಮ ಜನ್ಮ ರಾಶಿಯಿಂದ ಇಂದಿನ ಚಂದ್ರ ಎಲ್ಲಿದ್ದಾನೆ. ಇದು ಹಲವು ಅಂಶಗಳಲ್ಲಿ ಒಂದು, ನಿಮ್ಮ ದಿನದ ತೀರ್ಪಲ್ಲ.",
s7_n:"ಕುಂಡಲಿ ಹೊಂದಾಣಿಕೆ",
s7_d:"ಎರಡೂ ಜಾತಕಗಳಿಗೆ ಸಂಪೂರ್ಣ 36 ಗುಣ ಅಷ್ಟಕೂಟ ಹೊಂದಾಣಿಕೆ, ಜೊತೆಗೆ ಮಂಗಳ ದೋಷ, ಆಯುಷ್ಯ ವಿಚಾರ ಮತ್ತು ಕುಟುಂಬಗಳು ನಿಜವಾಗಿ ಕೇಳುವ ಪ್ರಾಯೋಗಿಕ ಪ್ರಶ್ನೆಗಳು.",
s8_n:"ಮುಹೂರ್ತ ಆಯ್ಕೆ",
s8_d:"ಮದುವೆ, ನೋಂದಣಿ, ಗೃಹಪ್ರವೇಶ, ಶಸ್ತ್ರಚಿಕಿತ್ಸೆ ಅಥವಾ ಹೊಸ ಉದ್ಯಮಕ್ಕೆ ಸರಿಯಾದ ದಿನಾಂಕ ಮತ್ತು ಸಮಯ — ನಿಮ್ಮ ಜಾತಕ ನೋಡಿ ಆರಿಸಿದ್ದು, ಮುದ್ರಿತ ಪಂಚಾಂಗದಿಂದ ಅಲ್ಲ.",
