modes_title:"ಗೌತಮ್ ಅವರೊಂದಿಗೆ ಮಾತನಾಡಲು ನಾಲ್ಕು ದಾರಿ",
modes_sub:"ನೀವು ಯಾವುದನ್ನು ಆರಿಸಿದರೂ ಜ್ಯೋತಿಷಿ ಒಬ್ಬರೇ. ಚಾಟ್ ನಿಮಿಷದ ಲೆಕ್ಕದಲ್ಲಿ; ಧ್ವನಿ, ವಿಡಿಯೋ ಮತ್ತು ಖುದ್ದು ಭೇಟಿ ನಿಗದಿತ ಶುಲ್ಕದಲ್ಲಿ — ಯಾವ ಮೀಟರೂ ಓಡುವುದಿಲ್ಲ.",
m1_n:"ಲೈವ್ ಚಾಟ್",
m1_d:"ನಿಮ್ಮ ಪ್ರಶ್ನೆ ಟೈಪ್ ಮಾಡಿ, ಯೋಚಿಸಿ ಕೊಟ್ಟ ಉತ್ತರ ಪಡೆಯಿರಿ. ಆರಂಭಿಸಲು ಸುಲಭ ದಾರಿ.",
m2_n:"ಧ್ವನಿ ಸಮಾಲೋಚನೆ",
m2_d:"ಒಂದು ಪೂರ್ಣ ದೂರವಾಣಿ ಸಂಭಾಷಣೆ. ನಿಮ್ಮ ಮಾತಿನಲ್ಲೇ ಪರಿಸ್ಥಿತಿ ವಿವರಿಸಬೇಕಿದ್ದರೆ ಉತ್ತಮ.",
m3_n:"ವಿಡಿಯೋ ಸಮಾಲೋಚನೆ",
