svc_sub:"ਹਰ ਸਲਾਹ ਖੁਦ ਆਚਾਰੀਆ ਗੌਤਮ ਦਿੰਦੇ ਹਨ — ਕਿਸੇ ਹੋਰ ਨੂੰ ਨਹੀਂ ਸੌਂਪੀ ਜਾਂਦੀ, ਨਾ ਹੀ ਆਟੋਮੈਟਿਕ ਹੈ।",
s1_n:"ਮੋਬਾਈਲ ਅੰਕ ਸ਼ਾਸਤਰ", s1_d:"ਜਾਣੋ ਤੁਹਾਡਾ ਫੋਨ ਨੰਬਰ ਤੁਹਾਡੀ ਕਿਸਮਤ, ਪੈਸੇ ਦੇ ਵਹਾਅ ਅਤੇ ਸਥਿਰਤਾ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ — ਅਤੇ ਕਿਹੜਾ ਨੰਬਰ ਤੁਹਾਡੇ ਲਈ ਵਧੀਆ ਹੈ।",
s2_n:"ਪ੍ਰਸ਼ਨ ਕੁੰਡਲੀ", s2_d:"ਇੱਕ ਜ਼ਰੂਰੀ ਸਵਾਲ, ਇੱਕ ਸਪਸ਼ਟ ਜਵਾਬ। ਜਨਮ ਸਮੇਂ ਦੀ ਲੋੜ ਨਹੀਂ — ਕੁੰਡਲੀ ਸਵਾਲ ਪੁੱਛਣ ਦੇ ਪਲ ਤੋਂ ਬਣਦੀ ਹੈ।",
s3_n:"ਜਨਮ ਕੁੰਡਲੀ ਵਿਸ਼ਲੇਸ਼ਣ", s3_d:"ਤੁਹਾਡੀ ਜਨਮ ਕੁੰਡਲੀ ਦਾ ਪੂਰਾ ਅਧਿਐਨ — ਕਰੀਅਰ, ਵਿਆਹ, ਪੈਸਾ, ਸਿਹਤ ਅਤੇ ਸਮਾਂ — ਅਜਿਹੇ ਉਪਾਵਾਂ ਨਾਲ ਜੋ ਤੁਸੀਂ ਸੱਚਮੁੱਚ ਕਰ ਸਕੋ।",
s4_n:"ਵਾਸਤੂ ਸਲਾਹ", s4_d:"ਆਪਣਾ ਫਲੋਰ ਪਲੈਨ ਭੇਜੋ ਅਤੇ ਕਮਰੇ-ਦਰ-ਕਮਰਾ ਵਾਸਤੂ ਰਿਪੋਰਟ ਲਵੋ — ਅਜਿਹੀਆਂ ਸੁਧਾਈਆਂ ਨਾਲ ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਕੰਧ ਤੋੜਨ ਦੀ ਲੋੜ ਨਹੀਂ।",
s5_n:"ਵਾਸਤੂ ਸਾਈਟ ਵਿਜ਼ਿਟ", s5_d:"ਆਚਾਰੀਆ ਗੌਤਮ ਖੁਦ ਤੁਹਾਡੇ ਘਰ ਜਾਂ ਜਾਇਦਾਦ ਤੇ ਆਉਂਦੇ ਹਨ, ਮੌਕੇ ਤੇ ਦਿਸ਼ਾਵਾਂ ਮਾਪਦੇ ਹਨ, ਅਤੇ ਲਿਖਤੀ ਯੋਜਨਾ ਦਿੰਦੇ ਹਨ।",
s6_n:"ਬਿਜ਼ਨਸ ਵਾਸਤੂ ਆਡਿਟ", s6_d:"ਦੁਕਾਨਾਂ, ਦਫ਼ਤਰਾਂ ਅਤੇ ਫੈਕਟਰੀਆਂ ਲਈ। ਬੈਠਣ ਦਾ ਪ੍ਰਬੰਧ, ਪ੍ਰਵੇਸ਼ ਦੁਆਰ, ਕੈਸ਼ ਕਾਊਂਟਰ ਅਤੇ ਸਟੋਰ — ਸਥਿਰਤਾ ਅਤੇ ਵਾਧੇ ਲਈ ਸੈੱਟ।",
