free_h:"ਸਮਝ ਨਹੀਂ ਆ ਰਿਹਾ ਕਿੱਥੋਂ ਸ਼ੁਰੂ ਕਰੀਏ? ਮੁਫ਼ਤ ਪੁੱਛੋ।",
free_p:"ਵਟਸਐਪ ਤੇ ਆਪਣੇ ਫਲੋਰ ਪਲੈਨ ਦੀ ਇੱਕ ਫੋਟੋ, ਜਾਂ ਕੁੰਡਲੀ ਬਾਰੇ ਇੱਕ ਸਵਾਲ ਭੇਜੋ। ਪਹਿਲੀ ਇਮਾਨਦਾਰ ਰਾਏ ਬਿਲਕੁਲ ਮੁਫ਼ਤ — ਅਤੇ ਕੁਝ ਵੀ ਬੁੱਕ ਕਰਨ ਦਾ ਕੋਈ ਦਬਾਅ ਨਹੀਂ।",
free_cta:"ਵਟਸਐਪ ਤੇ ਸੁਨੇਹਾ ਭੇਜੋ",
how_title:"ਪ੍ਰਕਿਰਿਆ ਕਿਵੇਂ ਚੱਲਦੀ ਹੈ",
h1_t:"ਆਪਣੀ ਸਮੱਸਿਆ ਦੱਸੋ", h1_d:"ਵਟਸਐਪ ਤੇ ਸੁਨੇਹਾ ਭੇਜੋ ਜਾਂ ਹੇਠਾਂ ਫਾਰਮ ਭਰੋ। ਜੋ ਸੱਚਮੁੱਚ ਪਰੇਸ਼ਾਨ ਕਰ ਰਿਹਾ ਹੈ ਉਹੀ ਦੱਸੋ — ਕਰੀਅਰ, ਵਿਆਹ, ਪੈਸਾ, ਜਾਇਦਾਦ।",
h2_t:"ਆਪਣੇ ਵੇਰਵੇ ਸਾਂਝੇ ਕਰੋ", h2_d:"ਜੋਤਿਸ਼ ਲਈ ਜਨਮ ਤਾਰੀਖ, ਸਮਾਂ ਅਤੇ ਥਾਂ। ਵਾਸਤੂ ਲਈ ਫਲੋਰ ਪਲੈਨ। ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਬੱਸ ਇੰਨਾ ਹੀ ਚਾਹੀਦਾ ਹੈ।",
h3_t:"ਸਲਾਹ-ਮਸ਼ਵਰਾ", h3_d:"ਇੱਕ ਪੂਰੀ ਗੱਲਬਾਤ — ਵੀਡੀਓ, ਫੋਨ ਜਾਂ ਰੂਬਰੂ — ਜਿੱਥੇ ਸਪਸ਼ਟ ਹੋਣ ਤੱਕ ਤੁਸੀਂ ਸਵਾਲ ਪੁੱਛ ਸਕਦੇ ਹੋ।",
h4_t:"ਲਿਖਤੀ ਰਿਪੋਰਟ ਅਤੇ ਉਪਾਅ", h4_d:"ਵਿਹਾਰਕ ਉਪਾਵਾਂ ਅਤੇ ਸਮੇਂ ਸਮੇਤ ਲਿਖਤੀ ਸਾਰ ਆਮ ਤੌਰ ਤੇ 24–48 ਘੰਟਿਆਂ ਵਿੱਚ ਮਿਲਦਾ ਹੈ।",
why_title:"ਲੋਕ ਗੌਤਮ ਸਪੀਕਸ ਨੂੰ ਕਿਉਂ ਚੁਣਦੇ ਹਨ",
w1_t:"ਇੱਕ ਜੋਤਸ਼ੀ, ਕੋਈ ਕਾਲ ਸੈਂਟਰ ਨਹੀਂ", w1_d:"ਹਰ ਵਾਰ ਤੁਸੀਂ ਖੁਦ ਆਚਾਰੀਆ ਗੌਤਮ ਨਾਲ ਹੀ ਗੱਲ ਕਰਦੇ ਹੋ — ਐਪ ਤੇ ਬਦਲਦੇ ਅਣਜਾਣ ਲੋਕਾਂ ਨਾਲ ਨਹੀਂ।",
w2_t:"ਤੁਹਾਡੀ ਭਾਸ਼ਾ ਵਿੱਚ ਸਲਾਹ", w2_d:"ਜਿਸ ਭਾਸ਼ਾ ਵਿੱਚ ਤੁਸੀਂ ਸੋਚਦੇ ਹੋ, ਉਸੇ ਵਿੱਚ ਸੇਧ ਮਿਲਦੀ ਹੈ, ਤਾਂ ਜੋ ਕੋਈ ਜ਼ਰੂਰੀ ਗੱਲ ਅਨੁਵਾਦ ਵਿੱਚ ਨਾ ਗੁਆਚੇ।",
w3_t:"ਅਜਿਹੇ ਉਪਾਅ ਜੋ ਤੁਸੀਂ ਕਰ ਸਕੋ", w3_d:"ਮਹਿੰਗੀਆਂ ਪੂਜਾਵਾਂ ਥੋਪੀਆਂ ਨਹੀਂ ਜਾਂਦੀਆਂ। ਤੁਹਾਡੀ ਜ਼ਿੰਦਗੀ ਅਤੇ ਬਜਟ ਵਿੱਚ ਫਿੱਟ ਹੋਣ ਵਾਲੇ ਸਧਾਰਨ, ਵਿਹਾਰਕ ਕਦਮ।",
w4_t:"ਪੂਰੀ ਗੁਪਤਤਾ", w4_d:"ਤੁਹਾਡੇ ਜਨਮ ਵੇਰਵੇ ਅਤੇ ਸਾਂਝੀਆਂ ਕੀਤੀਆਂ ਗੱਲਾਂ ਕਦੇ ਵੇਚੀਆਂ, ਸਾਂਝੀਆਂ ਜਾਂ ਕਿਸੇ ਹੋਰ ਕੰਮ ਲਈ ਨਹੀਂ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ।",
tst_title:"ਗਾਹਕ ਕੀ ਕਹਿੰਦੇ ਹਨ",
t1_q:"ਥਾਣੇ ਵਿੱਚ ਉੱਤਰ-ਮੁਖੀ ਫਲੈਟ ਲੈਣਾ ਹੈ ਜਾਂ ਨਹੀਂ, ਇਸ ਬਾਰੇ ਅਸੀਂ ਉਲਝੇ ਹੋਏ ਸੀ। ਸਾਈਟ ਵਿਜ਼ਿਟ ਨੇ ਦੋ ਸੁਧਾਈਆਂ ਨਾਲ ਸਪਸ਼ਟ ਹਾਂ ਕਹੀ। ਹਰ ਰੁਪਿਆ ਵਸੂਲ।", t1_r:"ਕਾਰੋਬਾਰੀ, ਥਾਣੇ",
t2_q:"ਦੋ ਸਾਲਾਂ ਤੋਂ ਮੈਂ ਤਰੱਕੀ ਦੀ ਉਡੀਕ ਕਰ ਰਿਹਾ ਸੀ। ਕੁੰਡਲੀ ਅਧਿਐਨ ਨੇ ਸਮਾਂ ਅਤੇ ਉਦੋਂ ਤੱਕ ਕੀ ਕਰਨਾ ਹੈ, ਦੋਵੇਂ ਸਮਝਾਏ। ਲਗਭਗ ਉਸੇ ਤਰ੍ਹਾਂ ਹੋਇਆ।", t2_r:"ਇੰਜੀਨੀਅਰ, ਪੁਣੇ",
t3_q:"ਵਿਹਾਰਕ, ਸ਼ਾਂਤ, ਅਤੇ ਇੱਕ ਵਾਰ ਵੀ ਡਰਾ ਕੇ ਕੁਝ ਵੇਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਨਹੀਂ ਕੀਤੀ। ਇਸੇ ਕਰਕੇ ਸਲਾਹ ਤੇ ਭਰੋਸਾ ਬਣਿਆ।", t3_r:"ਪ੍ਰੋਡਕਟ ਮੈਨੇਜਰ, ਮੁੰਬਈ",
faq_title:"ਅਕਸਰ ਪੁੱਛੇ ਜਾਣ ਵਾਲੇ ਸਵਾਲ",
q1:"ਜੇ ਮੈਨੂੰ ਆਪਣਾ ਸਹੀ ਜਨਮ ਸਮਾਂ ਨਹੀਂ ਪਤਾ ਤਾਂ?", a1:"ਫਿਰ ਵੀ ਲਾਭਦਾਇਕ ਅਧਿਐਨ ਸੰਭਵ ਹੈ। ਅਸੀਂ ਜਨਮ-ਸਮਾਂ ਸੁਧਾਈ ਕਰਦੇ ਹਾਂ, ਜਾਂ ਪ੍ਰਸ਼ਨ ਕੁੰਡਲੀ ਵੱਲ ਜਾਂਦੇ ਹਾਂ — ਜੋ ਸਵਾਲ ਪੁੱਛਣ ਦੇ ਪਲ ਤੋਂ ਬਣਦੀ ਹੈ ਅਤੇ ਜਿਸ ਵਿੱਚ ਜਨਮ ਸਮੇਂ ਦੀ ਲੋੜ ਹੀ ਨਹੀਂ।",
q2:"ਕੀ ਮੇਰੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਗੁਪਤ ਰਹਿੰਦੀ ਹੈ?", a2:"ਹਾਂ, ਪੂਰੀ ਤਰ੍ਹਾਂ। ਤੁਹਾਡੇ ਜਨਮ ਵੇਰਵੇ ਅਤੇ ਸਾਰੀ ਗੱਲਬਾਤ ਸਿਰਫ਼ ਤੁਹਾਡੇ ਅਤੇ ਆਚਾਰੀਆ ਗੌਤਮ ਵਿਚਕਾਰ ਰਹਿੰਦੀ ਹੈ। ਕੁਝ ਵੀ ਸਾਂਝਾ, ਵੇਚਿਆ ਜਾਂ ਪ੍ਰਕਾਸ਼ਿਤ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।",
q3:"ਕੀ ਤੁਸੀਂ ਮੁੰਬਈ ਤੋਂ ਬਾਹਰ ਵੀ ਸਲਾਹ ਦਿੰਦੇ ਹੋ?", a3:"ਆਨਲਾਈਨ ਸਲਾਹ ਵੀਡੀਓ ਜਾਂ ਫੋਨ ਰਾਹੀਂ ਦੁਨੀਆ ਵਿੱਚ ਕਿਤੇ ਵੀ ਉਪਲਬਧ ਹੈ। ਵਾਸਤੂ ਸਾਈਟ ਵਿਜ਼ਿਟ ਫਿਲਹਾਲ ਮੁੰਬਈ ਅਤੇ ਐਮਐਮਆਰ ਖੇਤਰ ਵਿੱਚ; ਹੋਰ ਸ਼ਹਿਰਾਂ ਲਈ ਸਫ਼ਰ ਵੱਖਰੇ ਤੌਰ ਤੇ ਤੈਅ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
q4:"ਕੀ ਮੇਰੇ ਤੇ ਰਤਨ ਜਾਂ ਪੂਜਾ ਖਰੀਦਣ ਦਾ ਦਬਾਅ ਪਾਇਆ ਜਾਵੇਗਾ?", a4:"ਨਹੀਂ। ਉਪਾਅ ਸਿਰਫ਼ ਉਦੋਂ ਦੱਸੇ ਜਾਂਦੇ ਹਨ ਜਦੋਂ ਸੱਚਮੁੱਚ ਲੋੜ ਹੋਵੇ, ਅਤੇ ਹਮੇਸ਼ਾ ਪਹਿਲਾਂ ਸਧਾਰਨ ਵਿਕਲਪ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ। ਕੁਝ ਵੀ ਖਰੀਦਣਾ ਜ਼ਰੂਰੀ ਨਹੀਂ।",
q5:"ਰਿਪੋਰਟ ਕਿੰਨੀ ਜਲਦੀ ਮਿਲੇਗੀ?", a5:"ਸਲਾਹ ਤੋਂ ਬਾਅਦ ਲਿਖਤੀ ਰਿਪੋਰਟ 24 ਤੋਂ 48 ਘੰਟਿਆਂ ਵਿੱਚ ਮਿਲ ਜਾਂਦੀ ਹੈ। ਜ਼ਰੂਰੀ ਪ੍ਰਸ਼ਨ ਕੁੰਡਲੀ ਦਾ ਜਵਾਬ ਆਮ ਤੌਰ ਤੇ ਉਸੇ ਦਿਨ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।",
form_title:"ਆਪਣੀ ਸਲਾਹ ਬੁੱਕ ਕਰੋ", form_sub:"ਇਹ ਭਰੋ ਅਤੇ ਅਸੀਂ ਵਟਸਐਪ ਤੇ ਗੱਲ ਅੱਗੇ ਵਧਾਵਾਂਗੇ। ਇਸ ਪੜਾਅ ਤੇ ਕੋਈ ਭੁਗਤਾਨ ਨਹੀਂ।",
