f_msg:"ਕਿਸ ਵਿਸ਼ੇ ਤੇ ਸੇਧ ਚਾਹੀਦੀ ਹੈ?", f_submit:"ਵਟਸਐਪ ਤੇ ਅੱਗੇ ਵਧੋ",
